// worker/auth.ts
// Uses the global `Env` generated by `npx wrangler types` (needs the DB binding).
import { hashPassword, verifyPassword, toHex } from './password';
import {
  ChangePasswordBody,
  CreateUserBody,
  LoginBody,
  UpdateUserBody,
  type Role,
  type UserDto,
} from '../shared/auth';
import { invalid, json, parseId, readJson } from './http';

export type { Role };
export interface User {
  id: number;
  email: string;
  role: Role;
}

// Over https (production) use the hardened __Host- cookie. Over plain http (local dev on
// http://localhost) browsers may reject Secure cookies, so fall back to a plain one there.
const COOKIE_HTTPS = '__Host-tc_session';
const COOKIE_HTTP = 'tc_session';
const isHttps = (req: Request) => new URL(req.url).protocol === 'https:';
const cookieName = (req: Request) => (isHttps(req) ? COOKIE_HTTPS : COOKIE_HTTP);
const TTL = 60 * 60 * 24 * 7;
const MAX_FAILS = 5;
const LOCK_SECS = 15 * 60;
// Burned on unknown emails so response time doesn't reveal which accounts exist
const DUMMY = 'pbkdf2-sha256$100000$' + '00'.repeat(16) + '$' + '00'.repeat(32);

const now = () => Math.floor(Date.now() / 1000);

const sha256Hex = async (s: string) =>
  toHex(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(s)));

function readCookie(req: Request, name: string): string | null {
  for (const part of (req.headers.get('Cookie') ?? '').split(';')) {
    const i = part.indexOf('=');
    if (i !== -1 && part.slice(0, i).trim() === name) return part.slice(i + 1).trim();
  }
  return null;
}

const setCookie = (req: Request, value: string, maxAge: number) =>
  isHttps(req)
    ? `${COOKIE_HTTPS}=${value}; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=${maxAge}`
    : `${COOKIE_HTTP}=${value}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${maxAge}`;

/** CSRF defence on top of SameSite: state-changing requests must come from our own origin. */
const crossOrigin = (req: Request): Response | null =>
  req.headers.get('Origin') === new URL(req.url).origin
    ? null
    : json({ error: 'Forbidden' }, { status: 403 });

/** Admin-only guard for handlers (the router also checks; this is the second lock). */
const notAdmin = (user: User): Response | null =>
  user.role === 'admin' ? null : new Response('Not found', { status: 404 });

// ---- Sessions ---------------------------------------------------------------

export async function getUser(req: Request, env: Env): Promise<User | null> {
  const token = readCookie(req, cookieName(req));
  if (!token) return null;
  return env.MGMT_DB.prepare(
    `SELECT u.id, u.email, u.role FROM sessions s JOIN users u ON u.id = s.user_id
     WHERE s.token_hash = ? AND s.expires_at > ? AND u.disabled = 0`
  )
    .bind(await sha256Hex(token), now())
    .first<User>();
}

export async function requireRole(req: Request, env: Env, ...roles: Role[]) {
  const user = await getUser(req, env);
  return user && roles.includes(user.role) ? user : null;
}

/** Counts a failed password attempt and locks the account after MAX_FAILS. */
async function registerFailure(env: Env, userId: number, previousFails: number) {
  const fails = previousFails + 1;
  const lock = fails >= MAX_FAILS;
  await env.MGMT_DB.prepare('UPDATE users SET failed_logins = ?, locked_until = ? WHERE id = ?')
    .bind(lock ? 0 : fails, lock ? now() + LOCK_SECS : 0, userId)
    .run();
}

// ---- Login / logout / status ------------------------------------------------

export async function handleLogin(req: Request, env: Env): Promise<Response> {
  const bad = crossOrigin(req);
  if (bad) return bad;

  const parsed = LoginBody.safeParse(await readJson(req));
  if (!parsed.success) return json({ error: 'Enter your email and password.' }, { status: 400 });
  const { email, password } = parsed.data;

  const row = await env.MGMT_DB.prepare(
    'SELECT id, password_hash, failed_logins, locked_until, disabled FROM users WHERE email = ?'
  )
    .bind(email)
    .first<{
      id: number;
      password_hash: string;
      failed_logins: number;
      locked_until: number;
      disabled: number;
    }>();

  const ok = await verifyPassword(password, row?.password_hash ?? DUMMY);
  const locked = !!row && row.locked_until > now();

  if (!row || !ok || row.disabled || locked) {
    if (row && !ok && !locked) await registerFailure(env, row.id, row.failed_logins);
    return json({ error: 'Invalid credentials' }, { status: 401 }); // same message for every failure
  }

  const token = toHex(crypto.getRandomValues(new Uint8Array(32)));
  await env.MGMT_DB.batch([
    env.MGMT_DB.prepare('UPDATE users SET failed_logins = 0, locked_until = 0 WHERE id = ?').bind(row.id),
    env.MGMT_DB.prepare('DELETE FROM sessions WHERE user_id = ? AND expires_at < ?').bind(row.id, now()),
    env.MGMT_DB.prepare('INSERT INTO sessions (token_hash, user_id, expires_at) VALUES (?, ?, ?)').bind(
      await sha256Hex(token),
      row.id,
      now() + TTL
    ),
  ]);
  return json({ ok: true }, { headers: { 'Set-Cookie': setCookie(req, token, TTL) } });
}

export async function handleLogout(req: Request, env: Env): Promise<Response> {
  const bad = crossOrigin(req);
  if (bad) return bad;

  const token = readCookie(req, cookieName(req));
  if (token) {
    await env.MGMT_DB.prepare('DELETE FROM sessions WHERE token_hash = ?').bind(await sha256Hex(token)).run();
  }
  return json({ loggedIn: false }, { headers: { 'Set-Cookie': setCookie(req, '', 0) } });
}

export async function handleStatus(req: Request, env: Env): Promise<Response> {
  const u = await getUser(req, env);
  return json(u ? { loggedIn: true, email: u.email, role: u.role } : { loggedIn: false });
}

// ---- Change own password (any logged-in user) -------------------------------

export async function handleChangePassword(req: Request, env: Env, user: User): Promise<Response> {
  const bad = crossOrigin(req);
  if (bad) return bad;

  const parsed = ChangePasswordBody.safeParse(await readJson(req));
  if (!parsed.success) return invalid(parsed.error);
  const { currentPassword, newPassword } = parsed.data;

  const row = await env.MGMT_DB.prepare(
    'SELECT password_hash, failed_logins, locked_until FROM users WHERE id = ?'
  )
    .bind(user.id)
    .first<{ password_hash: string; failed_logins: number; locked_until: number }>();
  if (!row) return json({ error: 'Unauthorized' }, { status: 401 });

  // A stolen session shouldn't be able to guess the current password forever.
  if (row.locked_until > now()) {
    return json({ error: 'Too many attempts. Try again later.' }, { status: 429 });
  }

  if (!(await verifyPassword(currentPassword, row.password_hash))) {
    await registerFailure(env, user.id, row.failed_logins);
    // 400, not 401, so the client doesn't mistake it for an expired session
    return json({ error: 'Current password is incorrect' }, { status: 400 });
  }

  if (newPassword === currentPassword) {
    return json({ error: 'New password must be different from the current one' }, { status: 400 });
  }

  const token = readCookie(req, cookieName(req));
  const keepHash = token ? await sha256Hex(token) : '';

  await env.MGMT_DB.batch([
    env.MGMT_DB.prepare(
      'UPDATE users SET password_hash = ?, failed_logins = 0, locked_until = 0 WHERE id = ?'
    ).bind(await hashPassword(newPassword), user.id),
    // sign out every other device, keep the one making this request
    env.MGMT_DB.prepare('DELETE FROM sessions WHERE user_id = ? AND token_hash != ?').bind(user.id, keepHash),
  ]);

  return json({ ok: true });
}

// ---- Admin: manage manager / user accounts ----------------------------------

interface UserRow {
  id: number;
  email: string;
  role: Role;
  disabled: number;
  created_at: number;
}

const toUserDto = (r: UserRow): UserDto => ({
  id: r.id,
  email: r.email,
  role: r.role,
  disabled: r.disabled === 1,
  createdAt: r.created_at,
});

/** Lists managers and users. Admin accounts are never listed or editable through the API. */
export async function handleListUsers(env: Env, admin: User): Promise<Response> {
  const no = notAdmin(admin);
  if (no) return no;

  const { results } = await env.MGMT_DB.prepare(
    `SELECT id, email, role, disabled, created_at FROM users
     WHERE role != 'admin' ORDER BY created_at DESC`
  ).all<UserRow>();

  return json(results.map(toUserDto));
}

export async function handleCreateUser(req: Request, env: Env, admin: User): Promise<Response> {
  const bad = crossOrigin(req);
  if (bad) return bad;
  const no = notAdmin(admin);
  if (no) return no;

  const parsed = CreateUserBody.safeParse(await readJson(req));
  if (!parsed.success) return invalid(parsed.error);
  const { email, password, role } = parsed.data;

  try {
    await env.MGMT_DB.prepare('INSERT INTO users (email, password_hash, role, created_by) VALUES (?, ?, ?, ?)')
      .bind(email, await hashPassword(password), role, admin.id)
      .run();
  } catch (e) {
    if (String(e).includes('UNIQUE')) return json({ error: 'Email already exists' }, { status: 409 });
    throw e;
  }
  return json({ ok: true }, { status: 201 });
}

/** Enable/disable an account and/or reset its password. Either way their sessions are ended. */
export async function handleUpdateUser(
  req: Request,
  env: Env,
  admin: User,
  userIdSegment: string | undefined
): Promise<Response> {
  const bad = crossOrigin(req);
  if (bad) return bad;
  const no = notAdmin(admin);
  if (no) return no;

  const userId = parseId(userIdSegment);
  if (userId === null) return json({ error: 'Invalid id' }, { status: 400 });

  const parsed = UpdateUserBody.safeParse(await readJson(req));
  if (!parsed.success) return invalid(parsed.error);
  const { disabled, password } = parsed.data;

  const target = await env.MGMT_DB.prepare(`SELECT id FROM users WHERE id = ? AND role != 'admin'`)
    .bind(userId)
    .first();
  if (!target) return json({ error: 'Not found' }, { status: 404 });

  const statements: D1PreparedStatement[] = [];
  if (disabled !== undefined) {
    statements.push(env.MGMT_DB.prepare('UPDATE users SET disabled = ? WHERE id = ?').bind(disabled ? 1 : 0, userId));
  }
  if (password !== undefined) {
    statements.push(
      env.MGMT_DB.prepare(
        'UPDATE users SET password_hash = ?, failed_logins = 0, locked_until = 0 WHERE id = ?'
      ).bind(await hashPassword(password), userId)
    );
  }
  if (disabled === true || password !== undefined) {
    statements.push(env.MGMT_DB.prepare('DELETE FROM sessions WHERE user_id = ?').bind(userId));
  }

  await env.MGMT_DB.batch(statements);
  return json({ ok: true });
}

export async function handleDeleteUser(
  req: Request,
  env: Env,
  admin: User,
  userIdSegment: string | undefined
): Promise<Response> {
  const bad = crossOrigin(req);
  if (bad) return bad;
  const no = notAdmin(admin);
  if (no) return no;

  const userId = parseId(userIdSegment);
  if (userId === null) return json({ error: 'Invalid id' }, { status: 400 });

  const target = await env.MGMT_DB.prepare(`SELECT id FROM users WHERE id = ? AND role != 'admin'`)
    .bind(userId)
    .first();
  if (!target) return json({ error: 'Not found' }, { status: 404 });

  await env.MGMT_DB.batch([
    env.MGMT_DB.prepare('DELETE FROM sessions WHERE user_id = ?').bind(userId),
    env.MGMT_DB.prepare(`DELETE FROM users WHERE id = ? AND role != 'admin'`).bind(userId),
  ]);
  return new Response(null, { status: 204 });
}
